      if (started) return;
      started = true;
      if (doc && typeof doc.addEventListener === "function") {
        doc.addEventListener("visibilitychange", onVisibilityChange);
      }
      hidden = Boolean(doc && doc.hidden);
      if (hidden) status("paused");
      else connectSse();
